INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die Taktfrequenz der CPU der einzige Parameter, der die Leistung eines Systems bestimmt?', 2, '[{"text": "Nein", "correct": true, "because": "Kernanzahl und Cache sind ebenfalls entscheidend"}, {"text": "Ja", "correct": false, "because": "Leistung hängt von mehreren Faktoren ab"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Parameter ist für die Bewertung der RAM-Leistung am wichtigsten?', 3, '[{"text": "Taktfrequenz in MHz", "correct": true, "because": "Sie bestimmt die Datenrate"}, {"text": "Farbe des Moduls", "correct": false, "because": "Hat keinen Einfluss"}, {"text": "Anzahl der Pins", "correct": false, "because": "Nur Kompatibilität, nicht Leistung"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind folgende Aussagen richtig? a) Mehr Kerne erhöhen immer die Leistung. b) Höhere Taktfrequenz ist immer besser.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "Mehr Kerne helfen nur bei parallelen Aufgaben"}, {"text": "Beides stimmt", "correct": false, "because": "Taktfrequenz hängt vom Einsatz ab"}, {"text": "Nur b) stimmt", "correct": false, "because": "Nicht bei allen Anwendungen"}, {"text": "Beides falsch", "correct": true, "because": "Beides ist zu pauschal"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Parameter solltest du bei der Leistungsbewertung eines Motherboards priorisieren?', 4, '[{"text": "Anzahl der USB-Ports", "correct": false, "because": "Nur Zusatzfunktion"}, {"text": "Chipsatz und Erweiterbarkeit", "correct": true, "because": "Bestimmen Leistung und Zukunftssicherheit"}, {"text": "Markenname allein", "correct": false, "because": "Sagt wenig über Qualität aus"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann eine CPU mit geringer Taktfrequenz für Büroanwendungen ausreichend sein?', 2, '[{"text": "Ja", "correct": true, "because": "Bürosoftware benötigt wenig Rechenleistung"}, {"text": "Nein", "correct": false, "because": "Leistung hängt vom Einsatz ab"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist der Cache einer CPU wichtiger für die Leistung als die Anzahl der Kerne?', 2, '[{"text": "Nein", "correct": true, "because": "Es hängt von der Anwendung ab"}, {"text": "Ja", "correct": false, "because": "Cache allein entscheidet nicht immer"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor beeinflusst die Leistung eines Systems bei Multitasking am meisten?', 3, '[{"text": "RAM-Kapazität", "correct": true, "because": "Mehr RAM unterstützt parallele Prozesse"}, {"text": "Festplattengeschwindigkeit", "correct": false, "because": "Weniger entscheidend für Multitasking"}, {"text": "Gehäusematerial", "correct": false, "because": "Hat keinen Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen richtig? a) Ein höherer RAM-Takt verbessert immer die Leistung. b) Ein Motherboard mit mehr Steckplätzen ist leistungsstärker.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "RAM-Takt hilft nur bei passender CPU"}, {"text": "Beides stimmt", "correct": false, "because": "Steckplätze erhöhen nicht direkt Leistung"}, {"text": "Nur b) stimmt", "correct": false, "because": "Steckplätze sind keine Leistungsparameter"}, {"text": "Beides falsch", "correct": true, "because": "Beides hängt von weiteren Faktoren ab"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Parameter solltest du bei der Leistungsbewertung einer GPU für Spiele beachten?', 4, '[{"text": "Anzahl der CUDA-Kerne", "correct": true, "because": "Bestimmt die Rechenleistung"}, {"text": "Farbe der Platine", "correct": false, "because": "Irrelevant für Leistung"}, {"text": "Anzahl der Lüfter", "correct": false, "because": "Nur Kühlung, nicht Leistung"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein System mit wenig RAM für Videobearbeitung geeignet sein?', 2, '[{"text": "Nein", "correct": true, "because": "Videobearbeitung braucht viel Arbeitsspeicher"}, {"text": "Ja", "correct": false, "because": "Leistung wäre stark eingeschränkt"}]');
INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist der Cache einer CPU wichtiger für die Leistung als die Anzahl der Kerne?', 2, '[{"text": "Nein", "correct": true, "because": "Es hängt von der Anwendung ab"}, {"text": "Ja", "correct": false, "because": "Cache allein entscheidet nicht immer"}]'),
('00000000-0000-0000-0000-000000000000', 'Welcher Faktor beeinflusst die Leistung eines Systems bei Multitasking am meisten?', 3, '[{"text": "RAM-Kapazität", "correct": true, "because": "Mehr RAM unterstützt parallele Prozesse"}, {"text": "Festplattengeschwindigkeit", "correct": false, "because": "Weniger entscheidend für Multitasking"}, {"text": "Gehäusematerial", "correct": false, "because": "Hat keinen Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen über Leistungsparameter richtig? a) Eine SSD verbessert die Systemgeschwindigkeit mehr als RAM. b) Mehr CPU-Kerne sind immer besser für Spiele.', 3, '[{"text": "Nur a) stimmt", "correct": false, "because": "SSD wirkt anders als RAM"}, {"text": "Beides stimmt", "correct": false, "because": "Spiele nutzen nicht immer viele Kerne"}, {"text": "Nur b) stimmt", "correct": false, "because": "SSD hat großen Einfluss"}, {"text": "Beides falsch", "correct": true, "because": "Beides ist kontextabhängig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Parameter solltest du bei der Leistungsbewertung einer Grafikkarte beachten?', 4, '[{"text": "Anzahl der CUDA-Kerne", "correct": true, "because": "Bestimmt die Rechenleistung"}, {"text": "Farbe der Platine", "correct": false, "because": "Irrelevant für Leistung"}, {"text": "Gewicht der Karte", "correct": false, "because": "Hat keinen Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Kann ein System mit geringer RAM-Taktfrequenz für Videobearbeitung geeignet sein?', 2, '[{"text": "Nein", "correct": true, "because": "Videobearbeitung braucht schnellen RAM"}, {"text": "Ja", "correct": false, "because": "Langsamer RAM bremst Prozesse aus"}]');
